class Solution:
    def resultsArray(self, nums, k):
        n = len(nums)
        res = [-1] * (n - k + 1)
        run = 1
        for i in range(n):
            if i and nums[i] == nums[i - 1] + 1: run += 1
            else: run = 1
            if i >= k - 1 and run >= k:
                res[i - k + 1] = nums[i]
        return res

