class Solution:
    def resultsArray(self, nums, k):
        n = len(nums)
        P = [0] * n
        for i in range(1, n):
            P[i] = P[i-1] + (1 if nums[i] == nums[i-1] + 1 else 0)
        res = []
        for l in range(n - k + 1):
            ok = P[l + k - 1] - P[l] == k - 1
            res.append(nums[l + k - 1] if ok else -1)
        return res

