    vector<int> resultsArray(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> P(n, 0);
        for (int i = 1; i < n; i++) P[i] = P[i-1] + (nums[i] == nums[i-1] + 1);
        vector<int> res;
        for (int l = 0; l + k <= n; l++)
            res.push_back(P[l+k-1] - P[l] == k - 1 ? nums[l+k-1] : -1);
        return res;
    }
};

